#!/usr/bin/env node
// scripts/gen-cli-bundle.mjs - bake cli/mupot.mjs into src/cli/bundle.generated.ts so
// GET /cli can serve the exact file bytes. A Worker cannot read the filesystem at request
// time and this repo has no wrangler text-module rule, so the file is embedded the same way
// the schema chain is (scripts/gen-schema-chain.mjs). scripts/check-cli-bundle-fresh.mjs
// (CI + tests/mupot-cli-route.test.ts) fails if this output drifts from cli/mupot.mjs.
//
//   node scripts/gen-cli-bundle.mjs          # write src/cli/bundle.generated.ts

import { createHash } from 'node:crypto'
import { realpathSync, readFileSync, writeFileSync } from 'node:fs'
import { dirname, join } from 'node:path'
import { fileURLToPath } from 'node:url'

const ROOT = join(dirname(fileURLToPath(import.meta.url)), '..')
export const CLI_SOURCE_FILE = join(ROOT, 'cli', 'mupot.mjs')
export const DEFAULT_OUTPUT_FILE = join(ROOT, 'src', 'cli', 'bundle.generated.ts')

/** Pure: the module text for the given CLI file contents. */
export function generateCliBundleModule(source) {
  if (/[^\x00-\x7f]/.test(source)) {
    throw new Error('cli/mupot.mjs must be ASCII-only (keeps served bytes identical to the file under any decoding)')
  }
  const sha = createHash('sha256').update(Buffer.from(source, 'utf8')).digest('hex')
  return [
    '// GENERATED by scripts/gen-cli-bundle.mjs from cli/mupot.mjs - do not edit.',
    '// Regenerate with: npm run gen:cli-bundle (CI runs scripts/check-cli-bundle-fresh.mjs).',
    `export const CLI_SHA256 = '${sha}'`,
    `export const CLI_SOURCE = ${JSON.stringify(source)}`,
    '',
  ].join('\n')
}

export function readCliSource() {
  return readFileSync(CLI_SOURCE_FILE, 'utf8')
}

// Resolve both sides through realpath: run via a symlink, process.argv[1] is the link and a plain
// string compare would silently skip the check (exit 0, nothing verified).
function isMain() {
  try {
    return Boolean(process.argv[1]) && realpathSync(process.argv[1]) === realpathSync(fileURLToPath(import.meta.url))
  } catch {
    return false
  }
}

if (isMain()) {
  writeFileSync(DEFAULT_OUTPUT_FILE, generateCliBundleModule(readCliSource()))
  process.stdout.write(`wrote ${DEFAULT_OUTPUT_FILE}\n`)
}
